public void testValidateOrbitReference_DifferentOrbitReference() throws ParserConfigurationException, IOException, SAXException, URISyntaxException {
    final File[] slstrFiles = TestUtils.getSlstrFiles();
    Document[] manifests = new Document[slstrFiles.length + 1];
    for (int i = 0; i < slstrFiles.length; i++) {
        manifests[i] = DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(slstrFiles[i]);
    }
    String orbitRef = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n" + "          <sentinel-safe:orbitReference>\n" + "            <sentinel-safe:orbitNumber groundTrackDirection=\"descending\" type=\"start\">60627</sentinel-safe:orbitNumber>\n" + "            <sentinel-safe:relativeOrbitNumber groundTrackDirection=\"descending\" type=\"start\">182</sentinel-safe:relativeOrbitNumber>\n" + "            <sentinel-safe:passNumber groundTrackDirection=\"descending\" type=\"start\">121254</sentinel-safe:passNumber>\n" + "            <sentinel-safe:relativePassNumber groundTrackDirection=\"descending\" type=\"start\">364</sentinel-safe:relativePassNumber>\n" + "            <sentinel-safe:cycleNumber>158</sentinel-safe:cycleNumber>\n" + "            <sentinel-safe:phaseIdentifier>2</sentinel-safe:phaseIdentifier>\n" + "          </sentinel-safe:orbitReference>";
    final DocumentBuilder documentBuilder = DocumentBuilderFactory.newInstance().newDocumentBuilder();
    manifests[manifests.length - 1] = documentBuilder.parse(new InputSource(new ByteArrayInputStream(orbitRef.getBytes("utf-8"))));
    PDUStitchingException e21 = assertThrows("Exception expected", PDUStitchingException.class, () -> Validator.validateOrbitReference(manifests));
