    final int month = (Integer) MONTH_TABLE.get(_dateImageWasTaken.substring(2, 5));
    final int year = Integer.parseInt(_dateImageWasTaken.substring(5, 7)) + YEAR_OFFSET;
    calendar.set(year, month - 1, days, 0, 0, 0);
    return calendar;
}

